css:
.pl421-container {
    position: relative;
    min-height: 100vh;
    padding: 0;
    background: #060b1f;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #e6ecff;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}

.pl421-container * {
    box-sizing: border-box;
}

.pl421-backdrop {
    position: absolute;
    inset: 0;
    pointer-events: none;
    background:
        radial-gradient(circle at 15% 10%, rgba(99,102,241,0.28) 0%, transparent 45%),
        radial-gradient(circle at 85% 0%, rgba(236,72,153,0.18) 0%, transparent 50%),
        radial-gradient(circle at 50% 100%, rgba(34,211,238,0.18) 0%, transparent 55%),
        linear-gradient(180deg, #070c22 0%, #0a1028 60%, #090d22 100%);
    z-index: 0;
}

.pl421-shell {
    position: relative;
    z-index: 1;
    max-width: 1180px;
    margin: 0 auto;
    padding: 32px 24px 56px;
}

.pl421-header {
    margin-bottom: 28px;
}

.pl421-header-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
    padding: 22px 26px;
    background: linear-gradient(135deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02));
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 20px;
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    box-shadow: 0 20px 45px rgba(5,10,30,0.45);
}

.pl421-brand {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
}

.pl421-brand-badge {
    width: 48px;
    height: 48px;
    border-radius: 14px;
    background: linear-gradient(135deg, #6366f1, #22d3ee);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 1.05rem;
    color: #0a0e27;
    letter-spacing: 0.04em;
    box-shadow: 0 8px 22px rgba(99,102,241,0.45);
    flex-shrink: 0;
}

.pl421-brand-text {
    min-width: 0;
}

.pl421-brand-text h1 {
    margin: 0;
    font-size: 1.35rem;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: #f5f7ff;
    line-height: 1.2;
}

.pl421-brand-sub {
    margin: 4px 0 0 0;
    color: #9aa6cf;
    font-size: 0.85rem;
    letter-spacing: 0.02em;
}

.pl421-period-pill {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    background: rgba(99,102,241,0.14);
    border: 1px solid rgba(99,102,241,0.35);
    border-radius: 999px;
    color: #c7d2fe;
    font-size: 0.9rem;
    font-weight: 500;
    white-space: nowrap;
}

.pl421-period-pill strong {
    color: #f5f7ff;
    font-weight: 700;
}

.pl421-period-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #22d3ee;
    box-shadow: 0 0 12px rgba(34,211,238,0.8);
    animation: pl421-pulse 1.8s ease-in-out infinite;
}

@keyframes pl421-pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.55; transform: scale(1.25); }
}

/* KPIs */
.pl421-kpis {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}

.pl421-kpi {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 18px 20px;
    background: linear-gradient(135deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 16px;
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    box-shadow: 0 10px 28px rgba(0,0,0,0.35);
    transition: transform 0.25s ease, border-color 0.25s ease;
}

.pl421-kpi:hover {
    transform: translateY(-2px);
    border-color: rgba(255,255,255,0.18);
}

.pl421-kpi-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.25rem;
    font-weight: 700;
    flex-shrink: 0;
}

.pl421-kpi-body {
    min-width: 0;
    flex: 1;
}

.pl421-kpi-label {
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #8b95c0;
    margin-bottom: 4px;
}

.pl421-kpi-value {
    font-size: 1.55rem;
    font-weight: 700;
    color: #f5f7ff;
    letter-spacing: -0.01em;
    line-height: 1.15;
    word-break: break-word;
}

.pl421-kpi-score .pl421-kpi-icon {
    background: rgba(99,102,241,0.2);
    color: #a5b4fc;
}
.pl421-kpi-score .pl421-kpi-value { color: #c7d2fe; }

.pl421-kpi-accuracy .pl421-kpi-icon {
    background: rgba(34,197,94,0.18);
    color: #6ee7a3;
}
.pl421-kpi-accuracy .pl421-kpi-value { color: #6ee7a3; }

.pl421-kpi-correct .pl421-kpi-icon {
    background: rgba(251,191,36,0.18);
    color: #fcd34d;
}
.pl421-kpi-correct .pl421-kpi-value { color: #fcd34d; }

.pl421-kpi-cash .pl421-kpi-icon {
    background: rgba(34,211,238,0.18);
    color: #67e8f9;
}
.pl421-kpi-cash .pl421-kpi-value { color: #67e8f9; }

/* Sections */
.pl421-briefing,
.pl421-problems,
.pl421-history,
.pl421-chart-section {
    background: linear-gradient(135deg, rgba(255,255,255,0.045), rgba(255,255,255,0.015));
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 20px;
    padding: 26px;
    margin-bottom: 22px;
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    box-shadow: 0 14px 38px rgba(0,0,0,0.35);
}

.pl421-section-head {
    margin-bottom: 18px;
}

.pl421-section-eyebrow {
    display: inline-block;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #a5b4fc;
    font-weight: 600;
    margin-bottom: 6px;
}

.pl421-section-head h2 {
    margin: 0;
    font-size: 1.25rem;
    font-weight: 700;
    color: #f5f7ff;
    letter-spacing: -0.01em;
    line-height: 1.3;
}

.pl421-round-title {
    color: #f5f7ff !important;
    font-weight: 700;
    font-size: 1.3rem !important;
    line-height: 1.3;
}

.pl421-round-context {
    color: #c2cae8;
    line-height: 1.65;
    font-size: 0.95rem;
    margin-bottom: 20px;
    padding: 16px 18px;
    background: rgba(99,102,241,0.06);
    border-left: 3px solid #6366f1;
    border-radius: 0 12px 12px 0;
}

.pl421-round-context strong { color: #f5f7ff; }

/* P&L table */
.pl421-pnl-wrap {
    margin-bottom: 16px;
}

.pl421-pnl-scroll {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    background: rgba(10,14,39,0.45);
}

.pl421-container table.pl-diag-pnl,
.pl421-container table.pl-diag-metrics {
    width: 100%;
    font-size: 0.88rem;
    border-collapse: collapse;
    margin: 0;
    color: #d4dbf5;
}

.pl421-container table.pl-diag-pnl thead,
.pl421-container table.pl-diag-metrics thead {
    background: linear-gradient(90deg, rgba(99,102,241,0.22), rgba(34,211,238,0.18));
}

.pl421-container table.pl-diag-pnl th,
.pl421-container table.pl-diag-metrics th {
    padding: 12px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 0.78rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #e6ecff;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    white-space: nowrap;
}

.pl421-container table.pl-diag-pnl td,
.pl421-container table.pl-diag-metrics td {
    padding: 10px 14px;
    border-bottom: 1px solid rgba(255,255,255,0.05);
    vertical-align: top;
}

.pl421-container table.pl-diag-pnl tr:hover td,
.pl421-container table.pl-diag-metrics tr:hover td {
    background: rgba(255,255,255,0.03);
}

.pl421-container table.pl-diag-pnl tr:last-child td,
.pl421-container table.pl-diag-metrics tr:last-child td {
    border-bottom: none;
}

.pl421-container table.pl-diag-pnl tr.pl-diag-pnl-total td {
    font-weight: 700;
    border-top: 2px solid rgba(99,102,241,0.55);
    background: rgba(99,102,241,0.1);
    color: #f5f7ff;
}

.pl421-container table.pl-diag-pnl tr.pl-diag-pnl-revenue td {
    color: #6ee7a3;
    font-weight: 600;
    background: rgba(34,197,94,0.05);
}

.pl421-container table.pl-diag-pnl tr.pl-diag-pnl-negative td {
    color: #fca5a5;
    font-weight: 600;
}

.pl421-metrics-wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.pl421-metrics-wrap table.pl-diag-metrics {
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    overflow: hidden;
}

/* Problems list */
.pl421-problems-hint {
    color: #9aa6cf;
    font-size: 0.88rem;
    margin: 0;
    line-height: 1.55;
}

.pl421-problems-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.pl421-sim-problem-item {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 16px 18px;
    background: linear-gradient(135deg, rgba(255,255,255,0.035), rgba(255,255,255,0.012));
    border: 1.5px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    cursor: pointer;
    transition: border-color 0.2s ease, background 0.2s ease, transform 0.15s ease;
    user-select: none;
}

.pl421-sim-problem-item:hover {
    border-color: rgba(165,180,252,0.35);
    background: rgba(99,102,241,0.08);
}

.pl421-sim-problem-item.selected {
    border-color: #818cf8;
    background: linear-gradient(135deg, rgba(99,102,241,0.18), rgba(34,211,238,0.10));
    box-shadow: 0 0 0 1px rgba(129,140,248,0.25), 0 8px 22px rgba(99,102,241,0.25);
}

.pl421-sim-problem-item input[type="checkbox"] {
    flex-shrink: 0;
    margin: 0;
    width: 20px;
    height: 20px;
    accent-color: #6366f1;
    cursor: pointer;
}

.pl421-sim-problem-item span {
    flex: 1;
    min-width: 0;
    font-size: 0.95rem;
    line-height: 1.55;
    color: #d9defa;
    word-wrap: break-word;
    overflow-wrap: break-word;
}

.pl421-sim-problem-item.selected span {
    color: #f5f7ff;
    font-weight: 500;
}

/* Controls */
.pl421-controls {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: center;
    margin-bottom: 28px;
}

.pl421-btn-primary {
    appearance: none;
    border: none;
    cursor: pointer;
    padding: 14px 42px;
    font-size: 1rem;
    font-weight: 600;
    letter-spacing: 0.02em;
    color: #0a0e27;
    background: linear-gradient(135deg, #6366f1 0%, #22d3ee 100%);
    border-radius: 12px;
    box-shadow: 0 12px 28px rgba(99,102,241,0.4);
    transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
    min-height: 48px;
}

.pl421-btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 18px 36px rgba(99,102,241,0.55);
    filter: brightness(1.08);
}

.pl421-btn-primary:active {
    transform: translateY(0);
}

.pl421-btn-ghost {
    appearance: none;
    cursor: pointer;
    padding: 12px 24px;
    font-size: 0.9rem;
    font-weight: 500;
    color: #c7d2fe;
    background: transparent;
    border: 1px solid rgba(255,255,255,0.16);
    border-radius: 12px;
    transition: background 0.2s ease, border-color 0.2s ease;
    min-height: 44px;
}

.pl421-btn-ghost:hover {
    background: rgba(255,255,255,0.06);
    border-color: rgba(255,255,255,0.3);
}

/* History table */
.pl421-history-scroll {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    background: rgba(10,14,39,0.45);
}

.pl421-container table.pl421-history-table,
.pl421-container table#usfHistoryTable {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
    color: #d4dbf5;
    margin: 0;
}

.pl421-container table#usfHistoryTable thead {
    background: linear-gradient(90deg, rgba(99,102,241,0.22), rgba(34,211,238,0.18));
}

.pl421-container table#usfHistoryTable th {
    padding: 12px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 0.76rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #e6ecff;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    white-space: nowrap;
}

.pl421-container table#usfHistoryTable td {
    padding: 11px 14px;
    border-bottom: 1px solid rgba(255,255,255,0.05);
}

.pl421-container table#usfHistoryTable tr:last-child td {
    border-bottom: none;
}

.pl421-container table#usfHistoryTable tr:hover td {
    background: rgba(255,255,255,0.03);
}

/* Chart */
.pl421-chart-box {
    position: relative;
    width: 100%;
    min-height: 300px;
    padding: 12px;
    background: rgba(10,14,39,0.5);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
}

.pl421-chart-box canvas {
    max-width: 100%;
}

/* ===== Modal ===== */
.pl421-modal {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.pl421-modal.pl421-modal-open {
    display: flex;
}

.pl421-modal-overlay {
    position: absolute;
    inset: 0;
    background: rgba(4,8,24,0.78);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    animation: pl421-fade-in 0.25s ease both;
}

.pl421-modal-dialog {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 720px;
    max-height: 88vh;
    display: flex;
    flex-direction: column;
    background: linear-gradient(160deg, #131a3a 0%, #0f1631 100%);
    border: 1px solid rgba(129,140,248,0.35);
    border-radius: 22px;
    box-shadow: 0 30px 80px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.04);
    overflow: hidden;
    animation: pl421-rise 0.3s cubic-bezier(0.22,1,0.36,1) both;
}

@keyframes pl421-fade-in {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes pl421-rise {
    from { opacity: 0; transform: translateY(16px) scale(0.98); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

.pl421-modal-head {
    padding: 26px 28px 18px;
    background: linear-gradient(135deg, rgba(99,102,241,0.22), rgba(34,211,238,0.14));
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.pl421-modal-eyebrow {
    font-size: 0.72rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: #a5b4fc;
    font-weight: 600;
    margin-bottom: 8px;
}

.pl421-modal-title {
    margin: 0;
    font-size: 1.35rem;
    font-weight: 700;
    color: #f5f7ff;
    letter-spacing: -0.01em;
    line-height: 1.3;
}

.pl421-modal-score {
    margin-top: 12px;
    font-size: 1.05rem;
    font-weight: 600;
    color: #c7d2fe;
}

.pl421-modal-score .pl421-score-big {
    font-size: 1.8rem;
    font-weight: 800;
    background: linear-gradient(135deg, #a5b4fc, #67e8f9);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.pl421-modal-body {
    padding: 22px 28px;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    flex: 1;
}

.pl421-modal-footer {
    padding: 18px 28px 24px;
    border-top: 1px solid rgba(255,255,255,0.08);
    display: flex;
    justify-content: flex-end;
    background: rgba(6,11,31,0.5);
}

.pl421-modal-continue {
    min-width: 170px;
}

/* Feedback items inside modal */
.pl-diag-fb-correct,
.pl-diag-fb-missed,
.pl-diag-fb-wrong {
    padding: 14px 16px;
    margin-bottom: 10px;
    border-radius: 12px;
    font-size: 0.92rem;
    line-height: 1.55;
    color: #d9defa;
}

.pl-diag-fb-correct {
    background: rgba(34,197,94,0.1);
    border: 1px solid rgba(34,197,94,0.32);
    border-left: 4px solid #22c55e;
}

.pl-diag-fb-missed {
    background: rgba(239,68,68,0.1);
    border: 1px solid rgba(239,68,68,0.32);
    border-left: 4px solid #ef4444;
}

.pl-diag-fb-wrong {
    background: rgba(245,158,11,0.1);
    border: 1px solid rgba(245,158,11,0.32);
    border-left: 4px solid #f59e0b;
}

.pl-diag-fb-correct strong,
.pl-diag-fb-missed strong,
.pl-diag-fb-wrong strong {
    color: #f5f7ff;
}

.pl-diag-fb-lesson {
    margin-top: 16px;
    padding: 16px 18px;
    background: linear-gradient(135deg, rgba(99,102,241,0.14), rgba(34,211,238,0.1));
    border: 1px solid rgba(129,140,248,0.3);
    border-radius: 14px;
    color: #e6ecff;
    font-style: italic;
    line-height: 1.65;
}

.pl-diag-fb-lesson strong {
    color: #fcd34d;
    font-style: normal;
}

/* ===== Responsive ===== */
@media (max-width: 900px) {
    .pl421-shell {
        padding: 22px 16px 44px;
    }
    .pl421-brand-text h1 { font-size: 1.15rem; }
    .pl421-brand-sub { font-size: 0.78rem; }
    .pl421-section-head h2 { font-size: 1.1rem; }
    .pl421-round-title { font-size: 1.15rem !important; }
    .pl421-kpi-value { font-size: 1.35rem; }
}

@media (max-width: 640px) {
    .pl421-shell {
        padding: 18px 12px 40px;
    }
    .pl421-header-row {
        padding: 16px 18px;
        gap: 12px;
    }
    .pl421-brand {
        width: 100%;
    }
    .pl421-brand-badge {
        width: 40px;
        height: 40px;
        font-size: 0.95rem;
        border-radius: 12px;
    }
    .pl421-brand-text h1 { font-size: 1.05rem; }
    .pl421-brand-sub { font-size: 0.74rem; }
    .pl421-period-pill {
        width: 100%;
        justify-content: center;
    }
    .pl421-kpis {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .pl421-kpi {
        padding: 14px;
        gap: 10px;
    }
    .pl421-kpi-icon {
        width: 36px;
        height: 36px;
        font-size: 1rem;
        border-radius: 10px;
    }
    .pl421-kpi-value { font-size: 1.15rem; }
    .pl421-kpi-label { font-size: 0.65rem; }
    .pl421-briefing,
    .pl421-problems,
    .pl421-history,
    .pl421-chart-section {
        padding: 18px;
        border-radius: 16px;
    }
    .pl421-section-head h2 { font-size: 1rem; }
    .pl421-round-title { font-size: 1rem !important; }
    .pl421-round-context {
        padding: 12px 14px;
        font-size: 0.9rem;
    }
    .pl421-container table.pl-diag-pnl,
    .pl421-container table.pl-diag-metrics,
    .pl421-container table#usfHistoryTable {
        font-size: 0.8rem;
    }
    .pl421-container table.pl-diag-pnl th,
    .pl421-container table.pl-diag-pnl td,
    .pl421-container table.pl-diag-metrics th,
    .pl421-container table.pl-diag-metrics td,
    .pl421-container table#usfHistoryTable th,
    .pl421-container table#usfHistoryTable td {
        padding: 8px 10px;
    }
    .pl421-sim-problem-item {
        padding: 13px 14px;
        gap: 11px;
    }
    .pl421-sim-problem-item span {
        font-size: 0.88rem;
    }
    .pl421-controls {
        flex-direction: column;
    }
    .pl421-btn-primary,
    .pl421-btn-ghost {
        width: 100%;
    }
    .pl421-modal {
        padding: 12px;
    }
    .pl421-modal-dialog {
        max-height: 92vh;
        border-radius: 18px;
    }
    .pl421-modal-head {
        padding: 20px 20px 14px;
    }
    .pl421-modal-title { font-size: 1.1rem; }
    .pl421-modal-score { font-size: 0.95rem; }
    .pl421-modal-score .pl421-score-big { font-size: 1.5rem; }
    .pl421-modal-body {
        padding: 16px 20px;
    }
    .pl421-modal-footer {
        padding: 14px 20px 18px;
    }
    .pl421-modal-continue { width: 100%; }
